import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Body regions and integrity","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/combat/body-regions.md","filePath":"game-design/combat/body-regions.md"}'),i={name:"game-design/combat/body-regions.md"};function r(d,e,s,l,c,m){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="body-regions-and-integrity" tabindex="-1">Body regions and integrity <a class="header-anchor" href="#body-regions-and-integrity" aria-label="Permalink to &quot;Body regions and integrity&quot;">​</a></h1><p><strong>Design status: Accepted model and experimental normalization/lifecycle. Implementation: Stage 2A transient player body and lifecycle hooks; gameplay validation pending.</strong></p><p>The seven anatomical regions are <code>Head</code>, <code>Neck</code>, <code>Torso</code>, <code>LeftArm</code>, <code>RightArm</code>, <code>LeftLeg</code> and <code>RightLeg</code>. Left/right always means the target&#39;s anatomy. Each region has independent functional integrity; global Hits remain the life/death pool. Seven regions do <strong>not</strong> create seven independent death systems.</p><p>Only the actual impact region receives the primary Local Trauma. Shared sleeves or leggings do not merge left/right body state. <code>AnatomyProfile</code> is a gameplay concept, not an animation-body category.</p><h3 id="accepted-experimental-slice-0-scale" tabindex="-1">Accepted experimental Slice 0 scale <a class="header-anchor" href="#accepted-experimental-slice-0-scale" aria-label="Permalink to &quot;Accepted experimental Slice 0 scale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Integrity</th><th>Condition</th></tr></thead><tbody><tr><td>76–100</td><td>Healthy</td></tr><tr><td>51–75</td><td>Wounded</td></tr><tr><td>26–50</td><td>Injured</td></tr><tr><td>1–25</td><td>Severe</td></tr><tr><td>0</td><td>Disabled</td></tr></tbody></table><p>These values are test scaffolding, not final balance. The approved session-local policy initializes healthy, resets on successful resurrection/relog/restart/authorized body reset, and survives map or Combatant changes. Death invalidates it; failed resurrection must not heal a live body. There is no passive recovery, limb timer or persistence in this slice.</p><p>Body reset must not heal global HP, repair gear or automatically re-equip a shield. Stage 2A uses transient state, commits actual melee trauma and applies session/death/resurrection lifecycle rules. There is no authorized reset command in this minimal stage. <strong>Gap:</strong> observe accumulation and lifecycle in a two-player playtest.</p><h2 id="related-combat-foundation" tabindex="-1">Related combat foundation <a class="header-anchor" href="#related-combat-foundation" aria-label="Permalink to &quot;Related combat foundation&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/combat/limbs-and-trauma.html">Player guide: Limbs and Trauma</a> summarizes these rules. <a href="/Syrolands-Public/game-design/combat/damage.html#proposed-injuries-and-healing">Expanded injury and Healing proposals</a> do not change the seven-region mapping, thresholds or lifecycle above. Nonhuman and large-target applicability belongs to <a href="/Syrolands-Public/game-design/creatures.html">creature anatomy</a>, not animation body categories.</p>',10)])])}const p=a(i,[["render",r]]);export{h as __pageData,p as default};
